from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    pieces = list(tiles[:n])
    if h <= 0 or w <= 0 or len(pieces) != n:
        return False

    areas = [a * b for a, b in pieces]
    subset_areas = [set() for _ in range(1 << n)]
    subset_areas[0] = {0}
    for mask in range(1, 1 << n):
        bit = mask & -mask
        i = bit.bit_length() - 1
        subset_areas[mask] = subset_areas[mask ^ bit] | {
            value + areas[i] for value in subset_areas[mask ^ bit]
        }
    if h * w not in subset_areas[(1 << n) - 1]:
        return False

    full_row = (1 << w) - 1
    empty_rows = (0,) * h

    @lru_cache(maxsize=None)
    def search(occupied: Tuple[int, ...], used: int) -> bool:
        try:
            row = next(r for r in range(h) if occupied[r] != full_row)
        except StopIteration:
            return True

        col = next(c for c in range(w) if not (occupied[row] >> c) & 1)
        remaining_area = sum((full_row ^ row_mask).bit_count() for row_mask in occupied)
        if remaining_area not in subset_areas[((1 << n) - 1) ^ used]:
            return False

        for i, (a, b) in enumerate(pieces):
            if (used >> i) & 1:
                continue
            for height, width in {(a, b), (b, a)}:
                if row + height > h or col + width > w:
                    continue
                span = ((1 << width) - 1) << col
                if any(occupied[r] & span for r in range(row, row + height)):
                    continue
                updated = list(occupied)
                for r in range(row, row + height):
                    updated[r] |= span
                if search(tuple(updated), used | (1 << i)):
                    return True
        return False

    return search(empty_rows, 0)

