def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    """Count paths whose steps move one unit right or one unit up."""
    mod = 998244353
    prev_row = [0] * (W + 1)
    total = 0
    for y in range(H + 1):
        left = 0
        in_hole_row = D <= y <= U
        for x in range(W + 1):
            if in_hole_row and L <= x <= R:
                ways = 0
            else:
                ways = 1 + left + prev_row[x]
                if ways >= mod:
                    ways -= mod
                total += ways
                if total >= mod:
                    total -= mod
            left = ways
            prev_row[x] = ways
    return total

