def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count assignments whose result has at least k good substrings modulo 998244353.

    Deleting equal pairs and ABC triples reduces a substring to empty exactly when
    the three character counts have equal parity. In the quotient of F2^3 by
    {(0,0,0),(1,1,1)}, this means the prefix states at the two ends are equal.
    """
    mod = 998244353
    if k <= 0:
        return pow(3, s.count("?"), mod)
    if k > n * (n + 1) // 2:
        return 0

    # Represent the four quotient states as the elements of F2 x F2.
    # The letter steps are the three nonzero elements.
    step_for = {"A": 1, "B": 2, "C": 3}
    initial_counts = (1, 0, 0, 0)  # Include the prefix before the first character.
    dp = {(initial_counts, 0): 1}

    for ch in s:
        steps = (1, 2, 3) if ch == "?" else (step_for[ch],)
        nxt = {}
        for (counts, cur), ways in dp.items():
            for step in steps:
                dest = cur ^ step
                updated = list(counts)
                updated[dest] += 1
                key = (tuple(updated), dest)
                nxt[key] = (nxt.get(key, 0) + ways) % mod
        dp = nxt

    answer = 0
    for (counts, _), ways in dp.items():
        good = sum(c * (c - 1) // 2 for c in counts)
        if good >= k:
            answer = (answer + ways) % mod
    return answer

