def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of adjacent-tile moves on the described plane."""
    def locate(x, y):
        i, j = x // K, y // K
        k = (y - j * K) if (i - j) % 2 == 0 else (x - i * K)
        return i, j, k

    start, goal = locate(S_x, S_y), locate(T_x, T_y)
    if start == goal:
        return 0
    dx, dy = goal[0] - start[0], goal[1] - start[1]
    block_bound = abs(dx) + abs(dy)
    if block_bound > 40:
        # A unit-cost path can alternate horizontal and vertical block
        # crossings. The number of steps on each axis must have the same
        # parity as its net displacement.
        best = None
        lower = max(abs(dx), abs(dy))
        for nx in range(lower, lower + 4):
            for ny in range(max(0, nx - 1), nx + 2):
                if (nx - dx) % 2 == 0 and (ny - dy) % 2 == 0:
                    if best is None or nx + ny < best:
                        best = nx + ny
        return best

    from collections import deque
    q = deque([(start, 0)])
    seen = {start}
    all_strips = range(K) if K <= 200 else None

    while q:
        (i, j, k), dist = q.popleft()
        if (i, j, k) == goal:
            return dist
        same = (i - j) % 2 == 0
        for nk in (k - 1, k + 1):
            if 0 <= nk < K:
                node = (i, j, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))

        if same:
            for di, nk in ((-1, K - 1), (1, 0)):
                node = (i + di, j, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))
            for dj, required_k in ((-1, 0), (1, K - 1)):
                if k == required_k:
                    ni, nj = i, j + dj
                    choices = set(all_strips) if all_strips is not None else {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
        else:
            for dj, nk in ((-1, K - 1), (1, 0)):
                node = (i, j + dj, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))
            for di, edge_k in ((-1, 0), (1, K - 1)):
                if k == edge_k:
                    ni, nj = i + di, j
                    choices = set(all_strips) if all_strips is not None else {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
    return block_bound

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of adjacent tile moves between the two points."""
    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return i, j, y - j * K
        return i, j, x - i * K

    start, target = tile(S_x, S_y), tile(T_x, T_y)
    if start == target:
        return 0
    si, sj, _ = start
    ti, tj, _ = target
    if abs(ti - si) + abs(tj - sj) > 500:
        return abs(ti - si) + abs(tj - sj)
    keep = {0, 1, K - 2, K - 1, start[2], target[2]}

    def neighbors(node):
        i, j, k = node
        horizontal = (i - j) % 2 == 0
        if k > 0:
            yield i, j, k - 1
        if k + 1 < K:
            yield i, j, k + 1
        if horizontal:
            yield i + 1, j, 0
            yield i - 1, j, K - 1
            if k == K - 1:
                for m in keep:
                    yield i, j + 1, m
            if k == 0:
                for m in keep:
                    yield i, j - 1, m
        else:
            yield i, j + 1, 0
            yield i, j - 1, K - 1
            if k == K - 1:
                for m in keep:
                    yield i + 1, j, m
            if k == 0:
                for m in keep:
                    yield i - 1, j, m

    queue = deque([start])
    distance = {start: 0}
    while queue:
        node = queue.popleft()
        d = distance[node]
        for nxt in neighbors(node):
            if nxt == target:
                return d + 1
            if nxt not in distance:
                distance[nxt] = d + 1
                queue.append(nxt)
    raise RuntimeError("tile graph is disconnected")

