def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in [start, finish] ending with s whose digits
    are all at most limit.
    """
    if not s or any(ch < "0" or ch > "9" for ch in s):
        return 0
    if any(int(ch) > limit for ch in s):
        return 0

    suffix_value = int(s)
    suffix_length = len(s)
    suffix_scale = 10 ** suffix_length

    def count_prefixes_at_most(bound: int, length: int) -> int:
        """Count length-digit decimal prefixes (no leading zero) <= bound,
        with each digit at most limit.
        """
        if bound < 0:
            return 0
        text = str(bound)
        if len(text) < length:
            return 0
        if len(text) > length:
            return (limit * (limit + 1) ** (length - 1))
        total = 0
        for i, char in enumerate(text):
            digit = ord(char) - ord("0")
            low = 1 if i == 0 else 0
            remaining = length - i - 1
            choices_after = (limit + 1) ** remaining
            allowed_below = max(0, min(limit, digit - 1) - low + 1)
            total += allowed_below * choices_after
            if digit < low or digit > limit:
                return total
        return total + 1

    def count_up_to(bound: int) -> int:
        if bound < 1:
            return 0
        max_length = len(str(bound))
        answer = 0
        for total_length in range(suffix_length, max_length + 1):
            prefix_length = total_length - suffix_length
            if prefix_length == 0:
                # The suffix itself is a representation only if it has no
                # leading zero and denotes a positive integer.
                if s[0] != "0" and suffix_value <= bound:
                    answer += 1
            else:
                max_prefix = (bound - suffix_value) // suffix_scale
                answer += count_prefixes_at_most(max_prefix, prefix_length)
        return answer

    return count_up_to(finish) - count_up_to(start - 1)

