from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by digit sum.

    Args:
        l: The lower bound of the range (inclusive).
        r: The upper bound of the range (inclusive).

    Returns:
        The number of beautiful integers in the range.
    """

    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0

        digits = tuple(map(int, str(n)))
        length = len(digits)
        result = 0

        # A positive number with length digits has a digit sum from 1 to 9*length.
        for target_sum in range(1, 9 * length + 1):
            modulus = target_sum

            @lru_cache(maxsize=None)
            def visit(pos: int, remaining: int, product_mod: int,
                      started: bool, tight: bool) -> int:
                if remaining < 0 or remaining > 9 * (length - pos):
                    return 0
                if pos == length:
                    return int(remaining == 0 and started and product_mod == 0)

                upper = digits[pos] if tight else 9
                total = 0
                for digit in range(upper + 1):
                    next_started = started or digit != 0
                    next_remaining = remaining - digit
                    if next_remaining < 0:
                        continue
                    if not next_started:
                        next_product = product_mod
                    else:
                        next_product = (product_mod * digit) % modulus
                    total += visit(
                        pos + 1,
                        next_remaining,
                        next_product,
                        next_started,
                        tight and digit == upper,
                    )
                return total

            result += visit(0, target_sum, 1 % modulus, False, True)

        return result

    return count_up_to(r) - count_up_to(l - 1)

