def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements whose resulting string has at least k good substrings.

    A substring is good exactly when the three character counts have equal
    parity: deleting equal pairs preserves each parity, and deleting an ABC
    triple toggles all three parities together.
    """
    mod = 998244353
    if k <= 0:
        return pow(3, s.count("?"), mod)
    if k > n * (n + 1) // 2:
        return 0

    # Prefix parity vectors are considered modulo the all-ones vector, since
    # adding/removing one ABC triple changes all three coordinates together.
    # Represent the resulting four classes by two bits (A xor C, B xor C).
    # Each letter advances to a different nonzero class: A=1, B=2, C=3.
    moves = {"A": 1, "B": 2, "C": 3}
    # Key: counts at prefix class 0, 1, 2, followed by the current class.
    # The count at class 3 is inferred from the number of prefixes seen.
    dp = {(1, 0, 0, 0): 1}

    for ch in s:
        choices = (1, 2, 3) if ch == "?" else (moves[ch],)
        next_dp = {}
        for (c0, c1, c2, state), ways in dp.items():
            for move in choices:
                nxt = state ^ move
                if nxt == 0:
                    key = (c0 + 1, c1, c2, nxt)
                elif nxt == 1:
                    key = (c0, c1 + 1, c2, nxt)
                elif nxt == 2:
                    key = (c0, c1, c2 + 1, nxt)
                else:
                    key = (c0, c1, c2, nxt)
                next_dp[key] = (next_dp.get(key, 0) + ways) % mod
        dp = next_dp

    total_prefixes = n + 1
    answer = 0
    for (c0, c1, c2, _state), ways in dp.items():
        c3 = total_prefixes - c0 - c1 - c2
        good = (c0 * (c0 - 1) + c1 * (c1 - 1) +
                c2 * (c2 - 1) + c3 * (c3 - 1)) // 2
        if good >= k:
            answer = (answer + ways) % mod
    return answer

