from bisect import bisect_right
from functools import lru_cache
from math import isqrt


@lru_cache(maxsize=1)
def _non_square_perfect_powers():
    """Return sorted perfect powers <= 10**18 that are not squares."""
    limit = 10**18
    powers = set()

    # Any nonsquare perfect power has a representation with exponent >= 3.
    # Enumerating every exponent catches all such values; the set removes
    # duplicates such as 2**6 == 4**3.
    for exponent in range(3, 60):
        low, high = 1, 1
        while pow(high, exponent) <= limit:
            high *= 2
        while low + 1 < high:
            middle = (low + high) // 2
            if pow(middle, exponent) <= limit:
                low = middle
            else:
                high = middle
        base_limit = low

        for base in range(2, base_limit + 1):
            value = pow(base, exponent)
            if isqrt(value) ** 2 != value:
                powers.add(value)

    return sorted(powers)


def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] representable as a**b, b >= 2."""
    return isqrt(n) + bisect_right(_non_square_perfect_powers(), n)

