def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences of orientations of the graph described."""
    mod = 998244353

    # A relation is a 2 by 2 Boolean matrix. Bit (2 * a + b) means
    # that starting cycle-edge direction state a can reach state b.
    # At vertex i, with incoming edge state a_{i-1} and outgoing state
    # a_i, the cycle contributes 1 + a_{i-1} - a_i. A selected spoke
    # adds either zero or one to d_i.
    #
    # For any fixed sequence of d_i values, there can be several edge
    # orientations witnessing it. Propagating the whole relation from
    # both possible initial states determinizes this two-state automaton,
    # so each distinct sequence is counted exactly once.
    transitions = [[ [0] * 4 for _ in range(16)] for _ in range(2)]
    for has_spoke in range(2):
        for relation in range(16):
            for letter_index in range(4):
                value = letter_index - 1  # d_i - 1
                edge_relation = 0
                for before in range(2):
                    for after in range(2):
                        for spoke_in in range(has_spoke + 1):
                            if before - after + spoke_in == value:
                                edge_relation |= 1 << (2 * before + after)

                composed = 0
                for start in range(2):
                    current = (relation >> (2 * start)) & 3
                    reachable = 0
                    for before in range(2):
                        if current & (1 << before):
                            reachable |= (edge_relation >> (2 * before)) & 3
                    composed |= reachable << (2 * start)
                transitions[has_spoke][relation][letter_index] = composed

    # Begin with the identity relation: either initial state maps to itself.
    dp = [0] * 16
    dp[9] = 1
    for bit in s:
        table = transitions[bit == "1"]
        nxt = [0] * 16
        for relation, ways in enumerate(dp):
            if ways:
                for letter_index in range(4):
                    following = table[relation][letter_index]
                    if following:
                        nxt[following] = (nxt[following] + ways) % mod
        dp = nxt

    # A cyclic orientation exists exactly when the composed relation has
    # at least one diagonal entry, i.e. a starting state can return to itself.
    return sum(ways for relation, ways in enumerate(dp) if relation & 9) % mod

