from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    tiles = list(tiles[:n])
    if h <= 0 or w <= 0 or h * w > sum(a * b for a, b in tiles):
        return False

    cell_count = h * w
    full = (1 << cell_count) - 1
    areas = [a * b for a, b in tiles]

    possible = {0}
    for area in areas:
        possible |= {value + area for value in tuple(possible)}
    if cell_count not in possible:
        return False

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True

        remaining = cell_count - occupied.bit_count()
        sums = {0}
        for i, area in enumerate(areas):
            if not (used >> i) & 1:
                sums |= {value + area for value in tuple(sums)}
        if remaining not in sums:
            return False

        missing = full ^ occupied
        pos = (missing & -missing).bit_length() - 1
        row, col = divmod(pos, w)

        order = sorted(
            (i for i in range(len(tiles)) if not (used >> i) & 1),
            key=lambda i: areas[i],
            reverse=True,
        )
        for i in order:
            a, b = tiles[i]
            # Identical pieces are interchangeable; skip duplicate shapes at
            # this state while preserving all distinct orientations.
            shape = tuple(sorted((a, b)))
            if any(
                (used >> j) & 1 == 0 and tuple(sorted(tiles[j])) == shape
                for j in order[:order.index(i)]
            ):
                continue
            for rh, rw in {(a, b), (b, a)}:
                if row + rh > h or col + rw > w or rh * rw > remaining:
                    continue
                row_bits = ((1 << rw) - 1) << col
                placement = 0
                for rr in range(row, row + rh):
                    placement |= row_bits << (rr * w)
                if occupied & placement == 0 and search(
                    occupied | placement, used | (1 << i)
                ):
                    return True
        return False

    return search(0, 0)

