from functools import lru_cache


@lru_cache(maxsize=None)
def _ways(sum_target: int, positions: int, remaining_sum: int, product_mod: int, started: bool) -> int:
    """Count suffixes completing a digit sum and product residue."""
    if remaining_sum < 0 or remaining_sum > 9 * positions:
        return 0
    if positions == 0:
        return int(remaining_sum == 0 and started and product_mod == 0)

    total = 0
    for digit in range(10):
        next_sum = remaining_sum - digit
        if next_sum < 0:
            continue
        if not started and digit == 0:
            next_product = product_mod
            next_started = False
        elif not started:
            next_product = digit % sum_target
            next_started = True
        else:
            next_product = (product_mod * digit) % sum_target
            next_started = True
        total += _ways(
            sum_target, positions - 1, next_sum, next_product, next_started
        )
    return total


def _count_upto(bound: int) -> int:
    if bound <= 0:
        return 0

    digits = list(map(int, str(bound)))
    result = 0
    for target_sum in range(1, 9 * len(digits) + 1):
        prefix_sum = 0
        prefix_product = 1
        started = False

        for index, limit in enumerate(digits):
            remaining_positions = len(digits) - index - 1
            for digit in range(limit):
                if not started and digit == 0:
                    next_started = False
                    next_product = 1
                elif not started:
                    next_started = True
                    next_product = digit % target_sum
                else:
                    next_started = True
                    next_product = (prefix_product * digit) % target_sum

                needed_sum = target_sum - prefix_sum - digit
                result += _ways(
                    target_sum,
                    remaining_positions,
                    needed_sum,
                    next_product,
                    next_started,
                )

            if not started and limit == 0:
                continue
            if not started:
                started = True
                prefix_product = limit % target_sum
            else:
                prefix_product = (prefix_product * limit) % target_sum
            prefix_sum += limit

        if prefix_sum == target_sum and started and prefix_product == 0:
            result += 1

    return result


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by their digit sum."""
    return _count_upto(r) - _count_upto(l - 1)
